import time

_store = {}


def put(key, value, ttl):
    _store[key] = (value, time.time() + ttl)


def retry(read, times=3):
    for _ in range(times):
        value = read()
        if value is not None:
            return value
    return None


def get(key):
    def read():
        value, expires = _store.get(key, (None, 0))
        return value if time.time() < expires else None
    return retry(read)

